-- LOCAL Pro only. Accepted estimate -> original commercial reference, NOT a balance/debt.
-- No booking, financial posting, inventory, public quote or notification writes.
begin;
-- Exact immutable revision lookup for publication lineage; no history backfill.
create index if not exists pro_private_estimate_history_revision_lookup on public.pro_private_estimate_history(owner_id,estimate_id,((after_estimate->>'revision')::integer));
create table if not exists pro_private_estimate_work_agreements(
 owner_id uuid not null references profiles(id) on delete cascade,work_id text not null,publication_id uuid not null unique references pro_private_estimate_publications(id) on delete cascade,
 estimate_id uuid not null,version integer not null,estimate_revision integer not null,client_id text not null,title text not null,currency text not null check(currency in('CRC','USD')),total_cents bigint not null check(total_cents between 0 and 9000000000000),content_hash text not null,
 accepted_action_id uuid not null,accepted_actor_id uuid not null,accepted_at timestamptz not null,source_snapshot jsonb not null,work_snapshot jsonb not null,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,work_id),foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade);
create table if not exists pro_private_estimate_work_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,publication_id uuid not null references pro_private_estimate_publications(id) on delete cascade,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id));
create or replace function pro_private_estimate_work_json(p_work pro_work) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_work.id,'client',p_work.client,'service',p_work.service,'stage',p_work.stage,'start',p_work.start,'end',p_work."end",'clientId',p_work."clientId",'cancelled',p_work.cancelled,'bookingClientId',p_work."bookingClientId",'quoteId',p_work."quoteId",'externalQuoteId',p_work."externalQuoteId")$$;
create or replace function pro_private_estimate_work_agreement_json(p_agreement pro_private_estimate_work_agreements) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('publicationId',p_agreement.publication_id,'estimateId',p_agreement.estimate_id,'version',p_agreement.version,'estimateRevision',p_agreement.estimate_revision,'workId',p_agreement.work_id,'clientId',p_agreement.client_id,'title',p_agreement.title,'currency',p_agreement.currency,'totalCents',p_agreement.total_cents,'contentHash',p_agreement.content_hash,'acceptedActionId',p_agreement.accepted_action_id,'acceptedActorId',p_agreement.accepted_actor_id,'acceptedAt',p_agreement.accepted_at,'source',p_agreement.source_snapshot->'source','createdAt',p_agreement.created_at)$$;
-- Launch fix (2026-11-17, old bug 4): the projection keeps each line's section (group), exactly as the
-- publication writer does; without it every grouped quote failed «Historical publication content mismatch»,
-- so its acceptance never reached the job (agreed amount «Sin definir»).
create or replace function pro_private_estimate_work_source(p_actor uuid,p_publication uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v pro_private_estimate_publications;s pro_private_estimate_publication_states;e pro_private_estimate_publication_events;r pro_private_estimate_publication_actions;hist jsonb;snapshot jsonb;projected jsonb;lines jsonb;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into v from pro_private_estimate_publications where id=p_publication and owner_id=p_actor;if not found then raise exception 'Publication unavailable' using errcode='42501';end if;select * into s from pro_private_estimate_publication_states where publication_id=v.id;
 if s.status is distinct from 'accepted' then raise exception 'Actual client acceptance required' using errcode='40001';end if;
 select * into e from pro_private_estimate_publication_events where publication_id=v.id and action='accept' and revision=s.revision;
 if not found or e.actor_id is distinct from s.recipient_id or e.actor_id=p_actor then raise exception 'Acceptance evidence unavailable' using errcode='40001';end if;
 select * into r from pro_private_estimate_publication_actions where actor_id=e.actor_id and action_id=e.action_id;
 if found then
  if r.publication_id<>v.id or r.input->>'action' is distinct from 'accept' or r.input->>'publicationId' is distinct from v.id::text or r.input->>'contentHash' is distinct from v.content_hash or r.input->'revision' is distinct from to_jsonb(s.revision-1) or r.result->>'action' is distinct from 'accept' or r.result->'publication'->>'publicationId' is distinct from v.id::text or r.result->'publication'->'version' is distinct from to_jsonb(v.version) or r.result->'publication'->'revision' is distinct from to_jsonb(s.revision) or r.result->'publication'->>'contentHash' is distinct from v.content_hash or r.result->'publication'->'content' is distinct from v.content or r.result->'publication'->>'status' is distinct from 'accepted' then raise exception 'Acceptance receipt mismatch' using errcode='40001';end if;
 elsif exists(select 1 from profiles where id=e.actor_id) then raise exception 'Acceptance receipt unavailable' using errcode='40001';end if;
 select jsonb_agg(h.after_estimate) into hist from pro_private_estimate_history h where h.owner_id=p_actor and h.estimate_id=v.estimate_id and(h.after_estimate->>'revision')::integer=v.estimate_revision;
 if jsonb_array_length(coalesce(hist,'[]'::jsonb))<>1 then raise exception 'Historical source unavailable' using errcode='40001';end if;snapshot:=hist->0;
 if snapshot->>'id'<>v.estimate_id::text or snapshot->>'ownerId'<>p_actor::text or snapshot->>'clientId'<>v.client_id then raise exception 'Historical source identity mismatch' using errcode='40001';end if;
 select jsonb_agg(jsonb_build_object('id',value->'id','description',value->'description','unit',value->'unit','qtyMilli',value->'qtyMilli','unitPriceCents',value->'unitPriceCents','discountBps',value->'discountBps','taxBps',value->'taxBps')||jsonb_strip_nulls(jsonb_build_object('group',value->'group'))order by ord)into lines from jsonb_array_elements(snapshot->'lines')with ordinality e(value,ord);
 projected:=jsonb_build_object('title',snapshot->'title','currency',snapshot->'currency','validUntil',snapshot->'validUntil','notes',snapshot->'notes','issuer',jsonb_build_object('issuerName',snapshot->'issuer'->'issuerName','issuerIdType',snapshot->'issuer'->'issuerIdType','issuerId',snapshot->'issuer'->'issuerId','issuerEmail',snapshot->'issuer'->'issuerEmail','issuerPhone',snapshot->'issuer'->'issuerPhone','issuerAddress',snapshot->'issuer'->'issuerAddress'),'customer',jsonb_build_object('name',snapshot->'client'->'name','tradeName',snapshot->'client'->'tradeName','identification',snapshot->'client'->'identification','address',snapshot->'client'->'address'),'lines',lines,'subtotalCents',snapshot->'subtotalCents','discountCents',snapshot->'discountCents','taxCents',snapshot->'taxCents','totalCents',snapshot->'totalCents');
 if projected is distinct from v.content then raise exception 'Historical publication content mismatch' using errcode='40001';end if;
 return jsonb_build_object('publicationId',v.id,'estimateId',v.estimate_id,'estimateRevision',v.estimate_revision,'version',v.version,'publicationRevision',s.revision,'clientId',v.client_id,'title',v.content->'title','currency',v.content->'currency','totalCents',v.content->'totalCents','contentHash',v.content_hash,'source',snapshot->'source','sourceSnapshot',snapshot,'accepted',jsonb_build_object('actionId',e.action_id,'actorId',e.actor_id,'at',e.at));end $$;
create or replace function pro_private_estimate_work_reason(p_actor uuid,p_work text,p_client text,p_recipient uuid,p_publication uuid)returns text language plpgsql stable security invoker set search_path=public,pg_temp as $$declare w pro_work;begin
 select * into w from pro_work where user_id=p_actor and id=p_work;if not found then return 'source_unavailable';end if;
 if w."clientId" is distinct from p_client or w."bookingClientId" is not null and w."bookingClientId"<>p_recipient::text then return 'work_customer_changed';end if;if w.cancelled then return 'work_cancelled';end if;
 if exists(select 1 from pro_private_estimate_work_agreements where owner_id=p_actor and work_id=p_work and publication_id<>p_publication)then return 'work_already_linked';end if;
 if coalesce(w."quoteId",'')<>'' or coalesce(w."externalQuoteId",'')<>'' or exists(select 1 from pro_client_entries where user_id=p_actor and work_id=p_work and kind in('agreement','payment','payment_void'))then return 'legacy_finance';end if;return null;end $$;
create or replace function pro_private_estimate_work_mapping(p_actor uuid,p_publication uuid default null,p_work text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare a pro_private_estimate_work_agreements;w pro_work;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;if(p_publication is null)=(p_work is null)then raise exception 'Choose exactly one mapping scope' using errcode='22023';end if;
 select * into a from pro_private_estimate_work_agreements where owner_id=p_actor and(case when p_publication is not null then publication_id=p_publication else work_id=p_work end);
 if not found then return jsonb_build_object('agreement',null,'work',null);end if;
 select * into w from pro_work where user_id=p_actor and id=a.work_id;
 if not found or w."clientId"<>a.client_id or w."bookingClientId" is distinct from a.work_snapshot->>'bookingClientId' or coalesce(w."quoteId",'')<>coalesce(a.work_snapshot->>'quoteId','') or coalesce(w."externalQuoteId",'')<>coalesce(a.work_snapshot->>'externalQuoteId','') then raise exception 'Agreement work identity changed' using errcode='42501';end if;
 return jsonb_build_object('agreement',pro_private_estimate_work_agreement_json(a),'work',pro_private_estimate_work_json(w));end $$;
create or replace function pro_private_estimate_work_context(p_actor uuid,p_publication uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare evidence jsonb;c pro_clients;l pro_lead_center_records;m pro_manual_lead_works;w pro_work;mapping jsonb;required jsonb;manual jsonb;reason text;src jsonb;begin
 evidence:=pro_private_estimate_work_source(p_actor,p_publication);src:=evidence->'source';mapping:=pro_private_estimate_work_mapping(p_actor,p_publication,null);
 select * into c from pro_clients where user_id=p_actor and id=evidence->>'clientId';if not found then raise exception 'Private customer unavailable' using errcode='42501';end if;
 if c.archived then reason:='client_archived';end if;
 if src->>'kind'='work' then
  select * into w from pro_work where user_id=p_actor and id=src->>'id';if not found then reason:=coalesce(reason,'source_unavailable');else required:=jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text),'reason','source_work');end if;
 elsif src->>'kind'='manual' then
  select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=(src->>'id')::uuid;
  if not found then reason:=coalesce(reason,'source_unavailable');else
   select * into m from pro_manual_lead_works where owner_id=p_actor and lead_id=l.id;
   if found then select * into w from pro_work where user_id=p_actor and id=m.work_id_text;if not found then reason:=coalesce(reason,'source_unavailable');else required:=jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text),'reason','converted_manual');end if;
   else if l.archived then reason:=coalesce(reason,'source_archived');elsif l.client_id<>c.id then reason:=coalesce(reason,'source_customer_changed');end if;end if;
   manual:=jsonb_build_object('id',l.id,'currentRevision',l.revision,'canConvert',required is null and reason is null);
  end if;
 end if;
 if required is not null then reason:=coalesce(reason,pro_private_estimate_work_reason(p_actor,w.id,c.id,(evidence->'accepted'->>'actorId')::uuid,p_publication));end if;
 return jsonb_build_object('publicationId',p_publication,'contentHash',evidence->'contentHash','publicationRevision',evidence->'publicationRevision','version',evidence->'version','currency',evidence->'currency','totalCents',evidence->'totalCents','accepted',evidence->'accepted','source',src,'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived),'mapping',mapping->'agreement','requiredWork',required,'manual',manual,'canCreate',mapping->'agreement'='null'::jsonb and reason is null,'reason',case when mapping->'agreement'<>'null'::jsonb then null else reason end);end $$;
create or replace function pro_private_estimate_work_candidates(p_actor uuid,p_publication uuid,p_query text default '',p_after text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare evidence jsonb;ctx jsonb;items jsonb;next_id text;begin
 if p_query is null or length(p_query)>100 or p_after is not null and length(p_after)not between 1 and 160 then raise exception 'Invalid candidate query' using errcode='22023';end if;evidence:=pro_private_estimate_work_source(p_actor,p_publication);ctx:=pro_private_estimate_work_context(p_actor,p_publication);
 if ctx->'requiredWork'<>'null'::jsonb or ctx->'source'->>'kind'='manual' or not(ctx->>'canCreate')::boolean then return jsonb_build_object('items','[]'::jsonb,'nextCursor',null);end if;
 if p_after is not null and not exists(select 1 from pro_work w where w.user_id=p_actor and w.id=p_after and position(lower(p_query)in lower(w.service||' '||w.client))>0 and pro_private_estimate_work_reason(p_actor,w.id,evidence->>'clientId',(evidence->'accepted'->>'actorId')::uuid,p_publication)is null)then raise exception 'Candidate cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text))order by w.id),'[]'::jsonb)into items from(select * from pro_work w where w.user_id=p_actor and(p_after is null or w.id>p_after)and position(lower(p_query)in lower(w.service||' '||w.client))>0 and pro_private_estimate_work_reason(p_actor,w.id,evidence->>'clientId',(evidence->'accepted'->>'actorId')::uuid,p_publication)is null order by w.id limit 21)w;
 if jsonb_array_length(items)>20 then next_id:=items->19->'work'->>'id';items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
create or replace function pro_private_estimate_work_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_private_estimate_work_actions;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_private_estimate_work_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_private_estimate_work_mapping(p_actor,r.publication_id,null);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function pro_private_estimate_work_continue(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;pid uuid;wid text;child uuid;lead_rev integer;keys text[];r pro_private_estimate_work_actions;evidence jsonb;ctx jsonb;src jsonb;c pro_clients;l pro_lead_center_records;m pro_manual_lead_works;w pro_work;core_rev integer;row_json jsonb;answer jsonb;a pro_private_estimate_work_agreements;reason text;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)is distinct from'object' or(select array_agg(key order by key)from jsonb_object_keys(p_input)key)is distinct from array['action','actionId','contentHash','publicationId','publicationRevision','target'] or p_input->>'action'is distinct from'continue' then raise exception 'Invalid continuation' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;pid:=(p_input->>'publicationId')::uuid;wid:=p_input->'target'->>'workId';if aid is null or pid is null or length(wid)not between 1 and 160 or not coalesce(p_input->>'contentHash'~'^[a-f0-9]{64}$',false)or not coalesce(p_input->>'publicationRevision'~'^[0-9]+$',false) then raise exception 'Invalid continuation identity' using errcode='22023';end if;
 select array_agg(key order by key)into keys from jsonb_object_keys(p_input->'target')key;
 if p_input->'target'->>'kind'='existing' then if keys is distinct from array['fingerprint','kind','workId'] or not coalesce(p_input->'target'->>'fingerprint'~'^[a-f0-9]{32}$',false)then raise exception 'Invalid existing target' using errcode='22023';end if;
 elsif p_input->'target'->>'kind'='new' then if keys is distinct from array['conversionActionId','kind','leadRevision','workId']then raise exception 'Invalid new target' using errcode='22023';end if;perform wid::uuid;child:=(p_input->'target'->>'conversionActionId')::uuid;lead_rev:=(p_input->'target'->>'leadRevision')::integer;if(child is null)<>(lead_rev is null)or child=aid then raise exception 'Invalid child identity' using errcode='22023';end if;
 else raise exception 'Invalid target kind' using errcode='22023';end if;
 -- Global owner mutex is reentrant with client/core/conversion writers. Child
 -- conversion advisory precedes catalogue; no old writer locks this new ledger.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-private-estimate-work-action:'||p_actor::text||':'||aid::text,0));
 if child is not null then perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-work-action:'||p_actor::text||':'||child::text,0));end if;
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_private_estimate_work_actions where actor_id=p_actor and action_id=aid;if found then perform pro_private_estimate_work_mapping(p_actor,r.publication_id,null);if r.input is distinct from p_input then raise exception 'Continuation identity reused'using errcode='22023';end if;return r.result;end if;
 if exists(select 1 from pro_private_estimate_work_agreements where publication_id=pid) then raise exception 'Publication already linked'using errcode='40001';end if;
 evidence:=pro_private_estimate_work_source(p_actor,pid);src:=evidence->'source';
 if src->>'kind'='manual' then perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));end if;
 perform 1 from pro_private_estimates where owner_id=p_actor and id=(evidence->>'estimateId')::uuid for update;perform 1 from pro_private_estimate_publication_states where publication_id=pid for update;
 evidence:=pro_private_estimate_work_source(p_actor,pid);if evidence->>'contentHash'<>p_input->>'contentHash' or(evidence->>'publicationRevision')::integer<>(p_input->>'publicationRevision')::integer then raise exception 'Accepted publication changed'using errcode='40001';end if;
 if src->>'kind'='manual' then perform 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=(src->>'id')::uuid for update;end if;
 select * into c from pro_clients where user_id=p_actor and id=evidence->>'clientId' for update;if not found or c.archived then raise exception 'Restore the accepted customer first'using errcode='40001';end if;
 ctx:=pro_private_estimate_work_context(p_actor,pid);if not(ctx->>'canCreate')::boolean then raise exception 'Work continuation unavailable'using errcode='40001';end if;
 if ctx->'requiredWork'<>'null'::jsonb then if p_input->'target'->>'kind'<>'existing' or wid<>ctx->'requiredWork'->'work'->>'id' then raise exception 'Historical source work must be reused'using errcode='40001';end if;end if;
 if p_input->'target'->>'kind'='existing' then
  if src->>'kind'='manual' and ctx->'requiredWork'='null'::jsonb then raise exception 'Unconverted opportunity requires conversion'using errcode='40001';end if;
  -- NOWAIT avoids inverse old booking trigger order (work row -> owner mutex).
  begin select * into w from pro_work where user_id=p_actor and id=wid for update nowait;exception when lock_not_available then raise exception 'Work is being changed'using errcode='40001';end;
  if not found or md5(to_jsonb(w)::text)<>p_input->'target'->>'fingerprint'then raise exception 'Selected work changed'using errcode='40001';end if;
 else
  if ctx->'requiredWork'<>'null'::jsonb or exists(select 1 from pro_work where user_id=p_actor and id=wid)then raise exception 'New work identity unavailable'using errcode='40001';end if;
  if src->>'kind'='manual' then
   if child is null or lead_rev is null or lead_rev<1 or exists(select 1 from pro_manual_lead_works where owner_id=p_actor and action_id=child)then raise exception 'Conversion child identity unavailable'using errcode='40001';end if;
   select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=(src->>'id')::uuid;if l.client_id<>c.id or l.archived or l.revision<>lead_rev then raise exception 'Opportunity customer or revision changed'using errcode='40001';end if;
   perform pro_lead_commercial_work_convert(p_actor,jsonb_build_object('action','convert','actionId',child,'leadId',l.id,'leadRevision',lead_rev,'workId',wid));
   select * into w from pro_work where user_id=p_actor and id=wid;
  elsif src='null'::jsonb or src is null then
   if child is not null or lead_rev is not null then raise exception 'Direct work does not have a conversion child'using errcode='22023';end if;
   select revision into core_rev from pro_workspace_core where user_id=p_actor for update;
   row_json:=jsonb_build_object('id',wid,'client',c.name,'service',evidence->>'title','stage','new','start','','end','','clientId',c.id,'cancelled',false);perform pro_patch_core(p_actor,'work',row_json,coalesce(core_rev,0));select * into w from pro_work where user_id=p_actor and id=wid;
  else raise exception 'Historical source work must be reused'using errcode='40001';end if;
  if w.service<>evidence->>'title' then select revision into core_rev from pro_workspace_core where user_id=p_actor for update;row_json:=jsonb_strip_nulls(pro_private_estimate_work_json(w))||jsonb_build_object('service',evidence->>'title');perform pro_patch_core(p_actor,'work',row_json,core_rev);select * into w from pro_work where user_id=p_actor and id=wid;end if;
 end if;
 reason:=pro_private_estimate_work_reason(p_actor,wid,c.id,(evidence->'accepted'->>'actorId')::uuid,pid);if reason is not null then raise exception 'Existing finance or work identity conflicts with accepted estimate'using errcode='40001';end if;
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
 insert into pro_private_estimate_work_agreements(owner_id,work_id,publication_id,estimate_id,version,estimate_revision,client_id,title,currency,total_cents,content_hash,accepted_action_id,accepted_actor_id,accepted_at,source_snapshot,work_snapshot)values(p_actor,w.id,pid,(evidence->>'estimateId')::uuid,(evidence->>'version')::integer,(evidence->>'estimateRevision')::integer,c.id,evidence->>'title',evidence->>'currency',(evidence->>'totalCents')::bigint,evidence->>'contentHash',(evidence->'accepted'->>'actionId')::uuid,(evidence->'accepted'->>'actorId')::uuid,(evidence->'accepted'->>'at')::timestamptz,evidence->'sourceSnapshot',pro_private_estimate_work_json(w))returning * into a;
 answer:=jsonb_build_object('action','continue','agreement',pro_private_estimate_work_agreement_json(a),'work',pro_private_estimate_work_json(w));insert into pro_private_estimate_work_actions values(p_actor,aid,p_input,answer,pid,clock_timestamp());if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;return answer;end $$;
create or replace function pro_private_estimate_work_guard()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if exists(select 1 from pro_private_estimate_work_agreements where owner_id=old.user_id and work_id=old.id)then
  if tg_op='DELETE' then if exists(select 1 from profiles where id=old.user_id)then raise exception 'Accepted commercial work cannot be deleted'using errcode='23514';end if;return old;end if;
  if new.user_id is distinct from old.user_id or new.id is distinct from old.id or new."clientId"is distinct from old."clientId"or new."bookingClientId"is distinct from old."bookingClientId"or coalesce(new."quoteId",'')<>coalesce(old."quoteId",'')or coalesce(new."externalQuoteId",'')<>coalesce(old."externalQuoteId",'')then raise exception 'Accepted commercial work identity is immutable'using errcode='23514';end if;
 end if;return case when tg_op='DELETE'then old else new end;end $$;
create or replace function pro_private_estimate_work_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if tg_op='DELETE' then if tg_table_name='pro_private_estimate_work_agreements' then if not exists(select 1 from profiles where id=old.owner_id)then return old;end if;elsif tg_table_name='pro_private_estimate_work_actions'then if not exists(select 1 from profiles where id=old.actor_id)then return old;end if;end if;end if;raise exception 'Immutable accepted estimate work history'using errcode='23514';end $$;
drop trigger if exists pro_private_estimate_work_guard on pro_work;
create trigger pro_private_estimate_work_guard before update or delete on pro_work for each row execute function pro_private_estimate_work_guard();
drop trigger if exists pro_private_estimate_work_agreement_immutable on pro_private_estimate_work_agreements;
create trigger pro_private_estimate_work_agreement_immutable before update or delete on pro_private_estimate_work_agreements for each row execute function pro_private_estimate_work_immutable();
drop trigger if exists pro_private_estimate_work_action_immutable on pro_private_estimate_work_actions;
create trigger pro_private_estimate_work_action_immutable before update or delete on pro_private_estimate_work_actions for each row execute function pro_private_estimate_work_immutable();
do $$declare t text;f record;begin foreach t in array array['pro_private_estimate_work_agreements','pro_private_estimate_work_actions']loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public,anon,authenticated',t);execute format('grant all on %I to service_role',t);end loop;for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_private_estimate_work_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst, 'reload schema';
